// Layout (arrangement-only) — a responsive list/detail grid with consumer-owned slots.
// A frame-with-open-slots is Layout, NOT a Block (docs/rules/tier-convention.md § Tiers): it owns arrangement
// only. No Cmp token layer — references the Sys layout scales directly (component-contract
// §6 carve-out 5).
import type { CSSProperties, HTMLAttributes, ReactNode, Ref } from "react";
import "./SplitLayout.css";

export interface SplitLayoutProps extends Omit<HTMLAttributes<HTMLDivElement>, "className"> {
  /**
   * The list slot owns its own scrolling; SplitLayout deliberately does not scroll because a Layout
   * must not own focus behaviour for content it does not render. Wrap an independently scrolling
   * pane in ScrollArea, which measures overflow and takes a tab stop only when it actually overflows.
   */
  list: ReactNode;
  /**
   * The detail slot is responsible for its scrolling; SplitLayout leaves it unscrolled because a
   * Layout must not own focus behaviour for content it does not render. For independent pane scrolling,
   * wrap the detail in ScrollArea; it measures overflow and takes a tab stop only when it actually overflows.
   */
  detail: ReactNode;
  /** Width of the list pane from the medium step up, as a CSS length. The detail takes the rest. */
  listWidth?: string;
  /**
   * Fix the DETAIL pane instead, at this CSS length, and let the list take the rest: for a list
   * that is the working surface (a grid of items) beside a narrower inspector. When set,
   * `listWidth` is ignored, since only one pane can be fixed.
   */
  detailWidth?: string;
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLDivElement>;
}

export function SplitLayout({
  list,
  detail,
  listWidth = "20rem",
  detailWidth,
  className,
  style,
  ref,
  ...rest
}: SplitLayoutProps) {
  return (
    <div
      {...rest}
      ref={ref}
      className={className ? `sd-split-layout ${className}` : "sd-split-layout"}
      data-fixed-pane={detailWidth ? "detail" : "list"}
      style={
        {
          ...(detailWidth
            ? { "--sd-layout-detail-width": detailWidth }
            : { "--sd-layout-list-width": listWidth }),
          ...style,
        } as CSSProperties
      }
    >
      <div className="sd-split-layout__list">{list}</div>
      <div className="sd-split-layout__detail">{detail}</div>
    </div>
  );
}

/* SplitLayout.css — structural list/detail grid; slots retain their own look. */
/* Mobile-first: a single stacked column by default; the list/detail split appears at the
   md breakpoint (min-width, per the DS ladder). --sd-layout-list-width is a local
   intermediate (set inline from the `listWidth` prop), not a token. */
.sd-split-layout {
  /* Block inheritance of the inline per-instance --sd-layout-* var (see Container.css). */
  --sd-layout-list-width: initial;
  --sd-layout-detail-width: initial;
  display: grid;
  width: 100%;
  min-width: 0;
  min-height: 0;
  grid-template-columns: minmax(0, 1fr);
}

.sd-split-layout__list,
.sd-split-layout__detail {
  /* Layout tier rule: no overflow here; slot content owns its own scrolling and focus. */
  min-width: 0;
  min-height: 0;
}

@media (min-width: 768px) {
  /* `:where()` keeps the default at one class's weight, as before the attribute existed, so a
     consumer's own single-class override of the columns still wins. */
  .sd-split-layout:where([data-fixed-pane="list"]) {
    grid-template-columns: minmax(0, var(--sd-layout-list-width, 20rem)) minmax(0, 1fr);
  }
  /* The mirror: the list is the fluid working surface, the detail a fixed inspector at the end. */
  .sd-split-layout[data-fixed-pane="detail"] {
    grid-template-columns: minmax(0, 1fr) minmax(0, var(--sd-layout-detail-width));
  }
}
